<?php include 'header.php';if(isset($_GET['approve'])){$pdo->prepare("UPDATE members SET status='Approved' WHERE id=?")->execute([(int)$_GET['approve']]);header('Location:members.php');exit;}if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM members WHERE id=?')->execute([(int)$_GET['delete']]);header('Location:members.php');exit;}$rows=$pdo->query('SELECT * FROM members ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);?><h1>সদস্য Registration</h1><div class="panel"><table><tr><th>নাম</th><th>ফোন</th><th>ইমেইল</th><th>ঠিকানা</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['phone'])?></td><td><?=htmlspecialchars($r['email'])?></td><td><?=htmlspecialchars($r['address'])?></td><td><?=htmlspecialchars($r['status'])?></td><td><?php if($r['status']!=='Approved'):?><a href="?approve=<?=$r['id']?>">Approve</a> | <?php endif;?><a class="danger" href="?delete=<?=$r['id']?>" onclick="return confirm('Delete?')">Delete</a></td></tr><?php endforeach;?></table></div><?php include 'footer.php';?>